                module AntichristPatternA12
                ; Документация [исходная композиция](../../../../Docs/MusicComposition.md)
                assert $ == #EBE1
                ; Общий физический поток, ссылки 18A
Row00:          DB #FD, #1C                                                     ; орнамент 13, следующий байт является уже удвоенным индексом сэмпла
                DB #CD                                                          ; строка громкости 13
                DB #05                                                          ; отложенный эффект #05, параметры читаются после терминатора
                DB #B1, #0C                                                     ; перезагрузка длительности строки
                DB #66                                                          ; нота с индексом #16, завершение строки
                DB #03, #03                                                     ; параметры отложенного эффекта #05, порядок RET от последнего к первому
Row01:          DB #05                                                          ; отложенный эффект #05, параметры читаются после терминатора
                DB #6D                                                          ; нота с индексом #1D, завершение строки
                DB #06, #09                                                     ; параметры отложенного эффекта #05, порядок RET от последнего к первому
Row02:          DB #05                                                          ; отложенный эффект #05, параметры читаются после терминатора
                DB #B1, #08                                                     ; перезагрузка длительности строки
                DB #72                                                          ; нота с индексом #22, завершение строки
                DB #03, #03                                                     ; параметры отложенного эффекта #05, порядок RET от последнего к первому
Row03:          DB #05                                                          ; отложенный эффект #05, параметры читаются после терминатора
                DB #B1, #0C                                                     ; перезагрузка длительности строки
                DB #6A                                                          ; нота с индексом #1A, завершение строки
                DB #06, #06                                                     ; параметры отложенного эффекта #05, порядок RET от последнего к первому
Row04:          DB #05                                                          ; отложенный эффект #05, параметры читаются после терминатора
                DB #6D                                                          ; нота с индексом #1D, завершение строки
                DB #03, #03                                                     ; параметры отложенного эффекта #05, порядок RET от последнего к первому
Row05:          DB #05                                                          ; отложенный эффект #05, параметры читаются после терминатора
                DB #B1, #03                                                     ; перезагрузка длительности строки
                DB #76                                                          ; нота с индексом #26, завершение строки
                DB #01, #01                                                     ; параметры отложенного эффекта #05, порядок RET от последнего к первому
Row06:          DB #CC                                                          ; строка громкости 12
                DB #B1, #05                                                     ; перезагрузка длительности строки
                DB #D0                                                          ; завершение строки без новой ноты
End:            DB #00                                                          ; исходный нулевой байт физической границы потока, переход позиции описан в MusicPattern.md
                assert $ == #EC09
                endmodule
